<?php
namespace App\Features\Auth\Controllers;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Validation\Rules\Password;use Inertia\Inertia;use App\Features\Auth\Actions\LoginUserAction;use App\Features\Auth\Actions\RegisterUserAction;
class AuthController extends Controller {public function login(){return Inertia::render('Auth/Login');}public function authenticate(Request $r,LoginUserAction $action){$data=$r->validate(['username'=>'required|string','password'=>'required|string','remember'=>'boolean']);$action->execute($data);return redirect()->intended(auth()->user()->isAdmin()?route('admin.users.index'):route('dashboard.posts.index'));}public function register(){return Inertia::render('Auth/Register');}public function store(Request $r,RegisterUserAction $action){$data=$r->validate(['name'=>'required|string|max:120','username'=>'required|string|alpha_dash|min:3|max:40|unique:users,username','email'=>'required|email|max:255|unique:users,email','password'=>['required','confirmed',Password::min(8)->letters()->numbers()]]);$user=$action->execute($data);Auth::login($user);$r->session()->regenerate();return redirect()->route('dashboard.posts.index');}public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('home');}}
